// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

contract InvMutTest is Test {
    Wallet c;
    function setUp() public {
        c = new Wallet();
    }

    function testFuzz_property(address nonCreator, uint256 depositAmount, uint256 preBalanceNonCreator) public {
        vm.assume(nonCreator != address(0) && nonCreator != address(this));
        vm.assume(depositAmount > 0);
        vm.assume(preBalanceNonCreator <= type(uint256).max - depositAmount);

        vm.deal(nonCreator, depositAmount);
        vm.prank(nonCreator);
        c.deposit{value: depositAmount}();

        uint256 balanceBefore = nonCreator.balance;

        vm.prank(address(this));
        c.migrateTo(nonCreator);

        assertEq(nonCreator.balance - balanceBefore, depositAmount);
    }
}
